+/**
+ * Cuts the slug to at most `maxLength` characters, backing up to the last
+ * hyphen so words are not split, and drops any trailing hyphens.
+ */
+function truncateAtWordBoundary(slug: string, maxLength: number): string {
+  const truncated = slug.slice(0, Math.max(0, maxLength));
+  const lastHyphen = truncated.lastIndexOf("-");
+  const wholeWords = lastHyphen > 0 ? truncated.slice(0, lastHyphen) : truncated;
+  return wholeWords.replace(TRAILING_HYPHENS, "");
+}
